def total_with_tax(items, tax_rate=TAX_RATE):
    """Calculate total with tax, excluding tax-exempt items.

    Items may include a boolean field ``tax_exempt``. If set to True, the item is not
    subject to tax. All other items are taxed at ``tax_rate`` (default ``TAX_RATE``).
    The function returns the total amount rounded to two decimal places.
    """
    # Separate taxable and tax‑exempt items. ``tax_exempt`` may be missing; treat missing as False.
    taxable_items = [item for item in items if not item.get("tax_exempt", False)]
    exempt_items = [item for item in items if item.get("tax_exempt", False)]

    taxable_subtotal = sum(line_total(item["qty"], item["unit_price"]) for item in taxable_items)
    exempt_subtotal = sum(line_total(item["qty"], item["unit_price"]) for item in exempt_items)

    total = taxable_subtotal * (1 + tax_rate) + exempt_subtotal
    return round(total, 2)
