def line_total(qty, unit_price):
    return round(qty * unit_price, 2)


def subtotal(items):
    """Sum of line totals before tax.

    Args:
        items: Iterable of dicts each containing ``"qty"`` and ``"unit_price"``.
    Returns:
        Total of all line items, rounded to 2 decimal places.
    """
    return sum(line_total(item["qty"], item["unit_price"]) for item in items)


def apply_discount(amount, percent):
    """Apply a percentage discount to a monetary amount.

    The result is rounded to two decimal places (cents) to avoid floating
    point representation issues.
    """
    # TODO: reject percentages outside 0-100
    discounted = amount - amount * percent / 100
    return round(discounted, 2)


def total_with_tax(items, tax_rate=TAX_RATE):
    """Calculate the total price including tax.

    Args:
        items: Iterable of line items.
        tax_rate: Tax rate as a decimal (default 8%).
    Returns:
        Total amount after tax, rounded to two decimal places.
    """
    # TODO: items marked tax_exempt should not be taxed
    return round(subtotal(items) * (1 + tax_rate), 2)
